{
  "summary": "With an HFE letter issued on 15 June 2026, Mei Xin and Haziq should focus on timing, document preparation, eligibility checks specific to PR status, and post‑application steps to ensure a smooth BTO application.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "An HFE (Housing Flat Eligibility) letter is valid for 12 months from the issue date for first‑timer couples."
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "Mark the BTO sales launch date on your calendar and aim to submit the application within the first 48 hours of the online ballot opening, as early submissions have a higher chance of being processed."
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Gather all required documents before the launch, including NRICs, PR card, latest income documents, HFE letter (original or electronic copy), and any marriage certificate if applicable."
    },
    {
      "claim_id": "c4",
      "kind": "policy_fact",
      "text": "Since one applicant is a Singapore Permanent Resident, the couple is eligible for the BTO scheme but will only be eligible for the CPF Housing Grant (e.g., CPF Housing Grant for PRs) if the PR meets the minimum residency period (usually 5 years of PR status)."
    },
    {
      "claim_id": "c5",
      "kind": "caveat",
      "text": "The exact grant eligibility for PRs can change; verify the current CPF Housing Grant criteria on the HDB website (hdb.gov.sg) before applying."
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "Check that your combined monthly household income still falls within the income ceiling for the BTO project you intend to apply for; income ceilings differ by flat type and location."
    },
    {
      "claim_id": "c7",
      "kind": "caveat",
      "text": "Income ceiling limits are subject to periodic updates; confirm the latest figures on the HDB portal."
    },
    {
      "claim_id": "c8",
      "kind": "preparation_step",
      "text": "Ensure that neither applicant has any outstanding HDB loans, resale flat purchases, or private property ownership that would affect eligibility."
    },
    {
      "claim_id": "c9",
      "kind": "policy_fact",
      "text": "A change in household composition (e.g., birth of a child, addition of a new family member) after the HFE issuance requires a new HFE letter."
    },
    {
      "claim_id": "c10",
      "kind": "preparation_step",
      "text": "Set up a reliable internet connection and have a backup device ready for the online application, as the portal can experience high traffic during launch."
    },
    {
      "claim_id": "c11",
      "kind": "preparation_step",
      "text": "Review the flat selection criteria (e.g., proximity to MRT, school zones) ahead of time so you can quickly choose your preferred options during the ballot."
    },
    {
      "claim_id": "c12",
      "kind": "policy_fact",
      "text": "If you are successful in the ballot, you will have 30 days to sign the Agreement for Lease and pay the downpayment."
    },
    {
      "claim_id": "c13",
      "kind": "preparation_step",
      "text": "Prepare the required downpayment funds (typically 10% of the flat price) in your CPF Ordinary Account or cash, and ensure the CPF contribution ceiling is not exceeded."
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
